function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  const O = '#051428', Wood = '#8b5a2b', WoodLt = '#c48a4a', WoodDk = '#5a3a18';
  const Metal = '#9aa3ad', Eye = '#c43c3c', Shine = '#f0e8d6';

  // crate
  px(6, 10, 20, 18, O);
  px(7, 11, 18, 16, Wood);
  px(7, 11, 18, 2, WoodLt);
  px(7, 25, 18, 2, WoodDk);
  px(7, 11, 1, 16, WoodLt);
  px(24, 11, 1, 16, WoodDk);
  // X boards
  for (let i = 0; i < 16; i++) {
    px(8 + i, 12 + Math.floor(i * 14 / 15), 1, 2, WoodDk);
    px(23 - i, 12 + Math.floor(i * 14 / 15), 1, 2, WoodDk);
  }
  // lid seam
  px(7, 17, 18, 1, O);
  // peep eye in crack
  px(14, 14, 4, 3, O);
  px(15, 15, 2, 1, Eye);
  px(15, 15, 1, 1, Shine);
  // lock
  px(14, 20, 4, 5, Metal);
  px(15, 21, 2, 2, O);
}
